// ═══════════════════════════════════════════════════════════════
// STRUCTURATION DES DONNÉES PAR DESTINATAIRE ET NIVEAU D'ESCALADE
// SALARIÉS NON ATTACHÉS (XSAL)
// Niveaux : SALARIE / SUPERIEUR / FARHAT / BAALLAH / DGA / PDG
// ═══════════════════════════════════════════════════════════════

const items = $input.all();

console.log('\n═══════════════════════════════════════════════════');
console.log('📊 STRUCTURATION DES NOTIFICATIONS - SALARIÉS NON ATTACHÉS');
console.log('═══════════════════════════════════════════════════');
console.log(`Items reçus: ${items.length}`);

const notifications = {};

items.forEach(item => {
  const data = item.json;

  let destinatairePrincipal;
  let codeDestinataire;
  let typeDestinataire;

  if (data.niveau_escalade === 'PDG') {
    destinatairePrincipal = {
      code: data.code_pdg,
      nom: data.nom_pdg,
      prenom: data.prenom_pdg,
      email: data.email_pdg,
      telephone: data.telephone_pdg,
      chat_id: data.chat_id_pdg,
      langue: data.langue_pdg,
      bot: data.bot_pdg
    };
    codeDestinataire = data.code_pdg;
    typeDestinataire = 'PDG';

  } else if (data.niveau_escalade === 'DGA') {
    destinatairePrincipal = {
      code: data.code_dga,
      nom: data.nom_dga,
      prenom: data.prenom_dga,
      email: data.email_dga || null,
      telephone: data.telephone_dga || null,
      chat_id: null,
      langue: data.langue_dga || 'FRA',
      bot: null
    };
    codeDestinataire = data.code_dga;
    typeDestinataire = 'DGA';

  } else if (data.niveau_escalade === 'SUPERIEUR') {
    destinatairePrincipal = {
      code: data.code_sup_createur,
      nom: data.nom_sup_createur,
      prenom: data.prenom_sup_createur,
      email: data.email_sup_createur,
      telephone: data.tel_sup_createur,
      chat_id: data.chat_id_superieur,
      langue: data.langue_superieur,
      bot: data.bot_superieur
    };
    codeDestinataire = data.code_sup_createur;
    typeDestinataire = 'SUPERIEUR';

  // APRÈS
  } else if (data.niveau_escalade === 'SALARIE') {
      destinatairePrincipal = {
        code: data.code_createur,
        nom: data.nom_createur,
        prenom: data.prenom_createur,
        email: data.email_createur,
        telephone: data.tel_createur,
        chat_id: data.chat_id_createur,
        langue:  data.langue_createur || 'FRA',
        bot:     data.bot_createur
      };
      codeDestinataire = data.code_createur;
      typeDestinataire = 'SALARIE';

  } else if (data.niveau_escalade === 'FARHAT') {
    destinatairePrincipal = {
      code: data.code_farhat,
      nom: data.nom_farhat,
      prenom: data.prenom_farhat,
      email: data.email_farhat || null,
      telephone: data.telephone_farhat || null,
      chat_id: data.chat_id_farhat || null,
      langue: data.langue_farhat || 'FRA',
      bot: data.bot_farhat || null
    };
    codeDestinataire = data.code_farhat;
    typeDestinataire = 'FARHAT';

  } else if (data.niveau_escalade === 'BAALLAH') {
    destinatairePrincipal = {
      code: data.code_baallah,
      nom: data.nom_baallah,
      prenom: data.prenom_baallah,
      email: data.email_baallah || null,
      telephone: data.telephone_baallah || null,
      chat_id: data.chat_id_baallah || null,
      langue: data.langue_baallah || 'FRA',
      bot: data.bot_baallah || null
    };
    codeDestinataire = data.code_baallah;
    typeDestinataire = 'BAALLAH';

  } else {
    console.log(`⏭️  Salarié ${data.code_salarie} ignoré (niveau: ${data.niveau_escalade})`);
    return;
  }

  const cleDestinataire = `${typeDestinataire}_${codeDestinataire}`;

  if (!notifications[cleDestinataire]) {
    notifications[cleDestinataire] = {
      destinataire_principal: destinatairePrincipal,
      type_destinataire: typeDestinataire,
      niveau_escalade: data.niveau_escalade,

      salarie: {
        code: data.code_salarie,
        nom: data.nom,
        prenom: data.prenom,
        email: data.email,
        telephone: data.telephone,
        chat_id: data.chat_id_createur,
        langue: data.langue_createur ,
        bot: data.bot_createur,
        matricule: data.matricule,
        categorie: data.categorie,
        poste: data.poste,
        service: data.service
      },
      superieur: {
        code: data.code_sup_createur,
        nom: data.nom_sup_createur,
        prenom: data.prenom_sup_createur,
        email: data.email_sup_createur,
        telephone: data.tel_sup_createur,
        chat_id: data.chat_id_superieur,
        langue: data.langue_superieur,
        bot: data.bot_superieur
      },
      createur: {
        code: data.code_createur,
        nom: data.nom_createur,
        prenom: data.prenom_createur,
        email: data.email_createur,
        telephone: data.tel_createur
      },
      pdg: {
        code: data.code_pdg,
        nom: data.nom_pdg,
        prenom: data.prenom_pdg,
        email: data.email_pdg,
        telephone: data.telephone_pdg,
        chat_id: data.chat_id_pdg,
        langue: data.langue_pdg,
        bot: data.bot_pdg
      },
      dga: {
        code: data.code_dga,
        nom: data.nom_dga,
        prenom: data.prenom_dga,
        email: data.email_dga,
        telephone: data.telephone_dga,
        chat_id: null,
        langue: data.langue_dga || 'FRA',
        bot: null
      },
      farhat: {
        code: data.code_farhat,
        nom: data.nom_farhat,
        prenom: data.prenom_farhat,
        email: data.email_farhat,
        telephone: data.telephone_farhat,
        chat_id: data.chat_id_farhat,
        langue: data.langue_farhat,
        bot: data.bot_farhat
      },
      baallah: {
        code: data.code_baallah,
        nom: data.nom_baallah,
        prenom: data.prenom_baallah,
        email: data.email_baallah,
        telephone: data.telephone_baallah,
        chat_id: data.chat_id_baallah,
        langue: data.langue_baallah,
        bot: data.bot_baallah
      },

      salaries: []
    };
  }

  notifications[cleDestinataire].salaries.push({
    code_salarie:          data.code_salarie,
    matricule:             data.matricule,
    nom:                   data.nom,
    prenom:                data.prenom,
    email:                 data.email,
    telephone:             data.telephone,
    categorie:             data.categorie,
    poste:                 data.poste,
    service:               data.service,
    date_creation:         data.date_creation,
    date_controle:         data.date_controle,
    date_limite:           data.date_limite,
    jours_depuis_creation: data.jours_depuis_creation,
    jours_restants:        data.jours_restants,
    delai_int:             data.delai_int,
    seuil_dga:             data.seuil_dga,
    user_createur:         data.user_createur,
    code_createur:         data.code_createur,
    nom_createur:          data.nom_createur,
    prenom_createur:       data.prenom_createur,
    email_createur:        data.email_createur,
    tel_createur:          data.tel_createur
  });
});

const resultats = Object.values(notifications).map(notif => {
  const totalSalaries = notif.salaries.length;
  const joursMin = Math.min(...notif.salaries.map(s => s.jours_restants));
  const joursMax = Math.max(...notif.salaries.map(s => s.jours_restants));
  const delaiTotal = parseInt(notif.salaries[0]?.delai_int) || 10;
  const seuilDga = notif.salaries[0]?.seuil_dga || Math.floor(delaiTotal / 2);

  let emailCC   = [];
  let chatIDsCC = [];

  if (notif.type_destinataire === 'PDG') {
    if (notif.superieur.email)   emailCC.push(notif.superieur.email);
    if (notif.salarie.email)     emailCC.push(notif.salarie.email);
    if (notif.superieur.chat_id) chatIDsCC.push({
      chat_id: notif.superieur.chat_id, bot: notif.superieur.bot,
      langue: notif.superieur.langue,
      nom: `${notif.superieur.prenom} ${notif.superieur.nom}`
    });
    if (notif.salarie.chat_id) chatIDsCC.push({
      chat_id: notif.salarie.chat_id, bot: notif.salarie.bot,
      langue: notif.salarie.langue,
      nom: `${notif.salarie.prenom} ${notif.salarie.nom}`
    });

  } else if (notif.type_destinataire === 'SUPERIEUR') {
    if (notif.salarie.email)   emailCC.push(notif.salarie.email);
    if (notif.salarie.chat_id) chatIDsCC.push({
      chat_id: notif.salarie.chat_id, bot: notif.salarie.bot,
      langue: notif.salarie.langue,
      nom: `${notif.salarie.prenom} ${notif.salarie.nom}`
    });

  } else if (notif.type_destinataire === 'BAALLAH') {
    // BAALLAH → pas de CC
  } else if (notif.type_destinataire === 'FARHAT') {
    // FARHAT → pas de CC
  } else if (notif.type_destinataire === 'DGA') {
    // DGA → email uniquement, pas de CC
  }

  return {
    destinataire_principal: notif.destinataire_principal,
    type_destinataire:      notif.type_destinataire,
    niveau_escalade:        notif.niveau_escalade,
    email_cc:    emailCC.length   > 0 ? emailCC.join(',') : null,
    telegram_cc: chatIDsCC.length > 0 ? chatIDsCC         : null,
    salarie:   notif.salarie,
    superieur: notif.superieur,
    createur:  notif.createur,
    pdg:       notif.pdg,
    dga:       notif.dga,
    farhat:    notif.farhat,
    baallah:   notif.baallah,
    salaries:  notif.salaries,
    statistiques: {
      total_salaries: totalSalaries,
      jours_min:      joursMin,
      jours_max:      joursMax,
      priorite:       notif.niveau_escalade,
      delai_total:    delaiTotal,
      seuil_dga:      seuilDga
    },
    meta: {
      date_traitement:       new Date().toISOString(),
      langue_message:        notif.destinataire_principal.langue || 'FRA',
      peut_envoyer_email:    !!notif.destinataire_principal.email,
      peut_envoyer_telegram: !!notif.destinataire_principal.chat_id
    }
  };
});

console.log(`\n✅ Notifications structurées: ${resultats.length}`);
console.log('Par type:');
console.log(`  - PDG:       ${resultats.filter(r => r.type_destinataire === 'PDG').length}`);
console.log(`  - DGA:       ${resultats.filter(r => r.type_destinataire === 'DGA').length}`);
console.log(`  - Supérieur: ${resultats.filter(r => r.type_destinataire === 'SUPERIEUR').length}`);
console.log(`  - Salarié:   ${resultats.filter(r => r.type_destinataire === 'SALARIE').length}`);
console.log(`  - Farhat:    ${resultats.filter(r => r.type_destinataire === 'FARHAT').length}`);
console.log(`  - Baallah:   ${resultats.filter(r => r.type_destinataire === 'BAALLAH').length}`);
console.log('\nDétails:');
resultats.forEach(r => {
  console.log(`  ${r.type_destinataire} - ${r.destinataire_principal.nom}: ${r.statistiques.total_salaries} salarié(s)`);
});
console.log('═══════════════════════════════════════════════════\n');

return resultats.map(r => ({ json: r }));

