                   + ` — ${stats.total_salaries} salarié(s)`;

  let emailBody = `${T.salutation} ${destinataire.prenom} ${destinataire.nom},\n\n`;
  emailBody += `${T.introduction[data.type_destinataire]}\n\n`;
  emailBody += `═══════════════════════════════════════════════════════════════\n`;
  emailBody += `📊 ${T.section_stats}\n`;
  emailBody += `═══════════════════════════════════════════════════════════════\n\n`;
  emailBody += `${getEmoji(stats.jours_min)} Niveau d\'escalade : ${data.niveau_escalade}\n`;
  emailBody += `${T.total} : ${stats.total_salaries}\n`;
  emailBody += `${T.delai_min} : ${stats.jours_min} ${T.jours}\n`;
  emailBody += `${T.delai_total} : ${stats.delai_total} ${T.jours}\n`;
  if (data.type_destinataire === 'DGA') {
    emailBody += `${T.seuil_dga} : ${stats.seuil_dga} ${T.jours}\n`;
  }

  emailBody += `\n═══════════════════════════════════════════════════════════════\n`;
  emailBody += `👥 ${T.section_salaries}\n`;
  emailBody += `═══════════════════════════════════════════════════════════════\n\n`;

  // APRÈS
  salaries.forEach((sal, index) => {
      emailBody += `${index + 1}. ${getEmoji(sal.jours_restants)} ${sal.prenom} ${sal.nom} (${sal.code_salarie})\n`;
      emailBody += `   📁 N° Dossier : ${sal.code_salarie}\n`;
      if (sal.matricule) emailBody += `   🪪 ${T.matricule} : ${sal.matricule}\n`;
      if (sal.categorie) emailBody += `   📂 ${T.categorie} : ${sal.categorie}\n`;
      if (sal.poste)     emailBody += `   💼 ${T.poste} : ${sal.poste}\n`;
      if (sal.service)   emailBody += `   🏢 ${T.service} : ${sal.service}\n`;
      emailBody += `   📅 ${T.date_creation} : ${formaterDateHeure(sal.date_creation, langue)}\n`;
      emailBody += `   ⏰ ${T.jours_restants} : ${sal.jours_restants} ${T.jours} (${T.date_limite} : ${formaterDate(sal.date_limite, langue)})\n`;
      // ✅ NOUVEAU : Infos créateur
      if (sal.user_createur) {
        emailBody += `   👤 Créé par : ${sal.nom_createur || ''} ${sal.prenom_createur || ''} (${sal.user_createur})\n`;
        if (sal.email_createur)  emailBody += `   ✉️ Email créateur : ${sal.email_createur}\n`;
        if (sal.tel_createur)    emailBody += `   📞 Tél créateur : ${sal.tel_createur}\n`;
      }
      if (sal.jours_restants <= 2) emailBody += `   🚨 ${T.urgent}\n`;
      emailBody += `\n`;
  });

  emailBody += `═══════════════════════════════════════════════════════════════\n`;
  if (stats.jours_min <= 2) {
    emailBody += `🚨 ${T.action_requise} : ${T.urgent}\n`;
  } else if (data.type_destinataire === 'DGA') {
    emailBody += `📌 ${T.instruction_dga}\n`;
  } else {
    emailBody += `📌 ${T.instruction}\n`;
  }
  emailBody += `═══════════════════════════════════════════════════════════════\n\n`;
  emailBody += `📞 ${T.contact_rh} :\n`;
  if (data.superieur && data.superieur.email) {
    emailBody += `   ${data.superieur.prenom} ${data.superieur.nom}\n`;
    emailBody += `   Email : ${data.superieur.email}\n`;
    emailBody += `   Tél : ${data.superieur.telephone || 'N/A'}\n`;
  }
  emailBody += `\n${T.cordialement},\n\n${T.signature}\n\n`;
  emailBody += `━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n`;
  emailBody += `🤖 ${T.message_auto} — ${formaterDate(new Date().toISOString(), langue)}\n`;
  if (data.type_destinataire === 'PDG')    emailBody += `🔴 Notification URGENTE envoyée au PDG\n`;
  if (data.type_destinataire === 'DGA')    emailBody += `🟠 Notification DGA (seuil mi-délai : ${stats.seuil_dga}j)\n`;
  if (data.type_destinataire === 'BAALLAH') emailBody += `🟣 Notification Baallah\n`;
  emailBody += `${T.ne_pas_repondre}\n`;

  let telegramMessage = `${getEmoji(stats.jours_min)} *${T.sujet_email[data.type_destinataire]}*\n`;
  telegramMessage += `━━━━━━━━━━━━━━━━━━━━━\n\n`;
  telegramMessage += `👤 *${destinataire.prenom} ${destinataire.nom}*\n\n`;
  telegramMessage += `📊 *${T.section_stats}*\n`;
  telegramMessage += `${T.total} : *${stats.total_salaries}*\n`;
  telegramMessage += `${T.delai_min} : *${stats.jours_min} ${T.jours}*\n\n`;
  telegramMessage += `👥 *${T.section_salaries}*\n\n`;

  // APRÈS
  salaries.slice(0, 5).forEach((sal, index) => {
      telegramMessage += `${index + 1}. ${getEmoji(sal.jours_restants)} *${sal.prenom} ${sal.nom}*\n`;
      telegramMessage += `   📁 N° Dossier : \`${sal.code_salarie}\`\n`;
      if (sal.poste)   telegramMessage += `   💼 ${sal.poste}\n`;
      if (sal.service) telegramMessage += `   🏢 ${sal.service}\n`;
      telegramMessage += `   ⏰ ${sal.jours_restants} ${T.jours} ${T.jours_restants}\n`;
      // ✅ NOUVEAU : Créateur
      if (sal.user_createur) {
        telegramMessage += `   👤 Créateur : ${sal.nom_createur || sal.user_createur}\n`;
      }
      telegramMessage += `\n`;
  });
  if (salaries.length > 5) telegramMessage += `... et ${salaries.length - 5} autre(s) salarié(s)\n\n`;
  if (stats.jours_min <= 2) telegramMessage += `🚨 *${T.urgent}*\n\n`;

  return {
    email:    { subject: emailSubject, body: emailBody },
    telegram: { text: telegramMessage, parse_mode: 'Markdown' }
  };
}

function genererMessageCC(data, destinataireCC, typeDestinatairePrincipal) {
  const langue = destinataireCC.langue || data.meta.langue_message || 'FRA';
  const T = TEMPLATES[langue] || TEMPLATES.FRA;
  const stats = data.statistiques;
  const salaries = data.salaries;
  const destinatairePrincipal = data.destinataire_principal;

  const labels = {
    SUPERIEUR: T.cc_message.votre_superieur,
    PDG:       T.cc_message.le_pdg,
    DGA:       T.cc_message.le_dga,
    FARHAT:    T.cc_message.le_farhat,
    BAALLAH:   T.cc_message.le_baallah
  };
  const label = labels[typeDestinatairePrincipal] || typeDestinatairePrincipal;
  const msg_envoye_a       = `${label} *${destinatairePrincipal.prenom} ${destinatairePrincipal.nom}*`;
  const msg_envoye_a_email = `${label} ${destinatairePrincipal.prenom} ${destinatairePrincipal.nom}`;

  let emailSubject = `${T.copie_info} — ${T.sujet_email[typeDestinatairePrincipal]} — ${stats.total_salaries} salarié(s)`;

  let emailBody = `${T.salutation} ${destinataireCC.prenom} ${destinataireCC.nom},\n\n`;
  emailBody += `${T.cc_message.base} ${msg_envoye_a_email}.\n\n`;
  emailBody += `${getEmoji(stats.jours_min)} Niveau : ${data.niveau_escalade} | ${T.total} : ${stats.total_salaries} | ${T.delai_min} : ${stats.jours_min} ${T.jours}\n\n`;
  emailBody += `═══════════════════════════════════════════════════════════════\n`;
  emailBody += `👥 ${T.section_salaries}\n`;
  emailBody += `═══════════════════════════════════════════════════════════════\n\n`;

  salaries.forEach((sal, index) => {
    emailBody += `${index + 1}. ${getEmoji(sal.jours_restants)} ${sal.prenom} ${sal.nom} (${sal.code_salarie})\n`;
    emailBody += `   ⏰ ${sal.jours_restants} ${T.jours} ${T.jours_restants} (${T.date_limite} : ${formaterDate(sal.date_limite, langue)})\n`;
    if (sal.jours_restants <= 2) emailBody += `   🚨 ${T.urgent}\n`;
    emailBody += `\n`;
  });

  emailBody += `${T.cc_message.action}\n\n`;
  emailBody += `${T.cordialement},\n\n${T.signature}\n`;
  emailBody += `━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n`;
  emailBody += `🤖 ${T.message_auto} | ${T.copie_info} | ${T.ne_pas_repondre}\n`;

  let telegramMessage = `${T.copie_info}\n━━━━━━━━━━━━━━━━━━━━━\n\n`;
  telegramMessage += `${T.salutation} *${destinataireCC.prenom} ${destinataireCC.nom}*,\n\n`;
  telegramMessage += `${T.cc_message.base} ${msg_envoye_a}.\n\n`;
  telegramMessage += `📊 ${T.total} : *${stats.total_salaries}* | ${T.delai_min} : *${stats.jours_min} ${T.jours}*\n\n`;
  telegramMessage += `👥 *${T.section_salaries}*\n\n`;

  salaries.slice(0, 3).forEach((sal, index) => {
    telegramMessage += `${index + 1}. ${getEmoji(sal.jours_restants)} *${sal.prenom} ${sal.nom}*\n`;
    telegramMessage += `   ⏰ ${sal.jours_restants} ${T.jours} ${T.jours_restants}\n\n`;
  });
  if (salaries.length > 3) telegramMessage += `... et ${salaries.length - 3} autre(s) salarié(s)\n\n`;
  telegramMessage += `${T.cc_message.action}\n`;

  return {
    email:    { subject: emailSubject, body: emailBody },
    telegram: { text: telegramMessage, parse_mode: 'Markdown' }
  };
}

const results = [];

inputData.forEach(item => {
  const data = item.json;
  const messagesPrincipal = genererMessagePrincipal(data);

  results.push({
    json: {
      ...data,
      messages:           messagesPrincipal,
      type_envoi:         'PRINCIPAL',
      destinataire_final: data.destinataire_principal,
      meta: { ...data.meta, langue_utilisee: data.meta.langue_message || 'FRA', date_generation: new Date().toISOString() }
    }
  });

  // CC : SUPERIEUR → copie au salarié
  if (data.type_destinataire === 'SUPERIEUR' && data.salarie?.chat_id) {
    const messagesCC = genererMessageCC(data, data.salarie, 'SUPERIEUR');
    results.push({ json: {
      ...data, messages: messagesCC, type_envoi: 'CC',
      destinataire_final: data.salarie, cc_pour_profil: 'SALARIE',
      meta: { ...data.meta, langue_utilisee: data.salarie.langue || 'FRA', date_generation: new Date().toISOString() }
    }});
  }

  // CC : PDG → copie au supérieur + copie au salarié
  if (data.type_destinataire === 'PDG') {
    if (data.superieur?.chat_id) {
      const msgCCSup = genererMessageCC(data, data.superieur, 'PDG');
      results.push({ json: {
        ...data, messages: msgCCSup, type_envoi: 'CC',
        destinataire_final: data.superieur, cc_pour_profil: 'SUPERIEUR',
        meta: { ...data.meta, langue_utilisee: data.superieur.langue || 'FRA', date_generation: new Date().toISOString() }
      }});
    }
    if (data.salarie?.chat_id) {
      const msgCCSal = genererMessageCC(data, data.salarie, 'PDG');
      results.push({ json: {
        ...data, messages: msgCCSal, type_envoi: 'CC',
        destinataire_final: data.salarie, cc_pour_profil: 'SALARIE',
        meta: { ...data.meta, langue_utilisee: data.salarie.langue || 'FRA', date_generation: new Date().toISOString() }
      }});
    }
  }

  // CC : BAALLAH → copie au salarié
  if (data.type_destinataire === 'BAALLAH' && data.salarie?.chat_id) {
    const messagesCC = genererMessageCC(data, data.salarie, 'BAALLAH');
    results.push({ json: {
      ...data, messages: messagesCC, type_envoi: 'CC',
      destinataire_final: data.salarie, cc_pour_profil: 'SALARIE',
      meta: { ...data.meta, langue_utilisee: data.salarie.langue || 'FRA', date_generation: new Date().toISOString() }
    }});
  }

  // CC : FARHAT → copie au salarié
  if (data.type_destinataire === 'FARHAT' && data.salarie?.chat_id) {
    const messagesCC = genererMessageCC(data, data.salarie, 'FARHAT');
    results.push({ json: {
      ...data, messages: messagesCC, type_envoi: 'CC',
      destinataire_final: data.salarie, cc_pour_profil: 'SALARIE',
      meta: { ...data.meta, langue_utilisee: data.salarie.langue || 'FRA', date_generation: new Date().toISOString() }
    }});
  }
  // DGA → email uniquement, pas de CC, pas de Telegram
});

